// Regenerate shared/prefetch-fallback.min.ts from client/prefetch-fallback.ts: node libs/router/build/prefetch-script.ts
// The source is serialized with Function#toString (Node's type stripping leaves whitespace, esbuild's
// minifier normalizes it). `tests/prefetch.test.ts` fails when the generated file is stale.
import { writeFile } from "node:fs/promises";
import { transform } from "esbuild";
import { fallback } from "../client/prefetch-fallback.ts";

const CALL = "(SELECTOR)";
/** The minified fallback as a function expression (`(function(s){…})`); pages call it with their selector. */
export async function minifiedFallback(): Promise<string> {
  const code = (await transform("(" + fallback + ")" + CALL, { minify: true, target: "es2020" })).code.trim().replace(/;$/, "");
  if (!code.endsWith(CALL)) throw new Error("prefetch-script: unexpected minifier output");
  return code.slice(0, -CALL.length);
}

if (import.meta.url === new URL(process.argv[1]!, "file://").href) {
  const code = await minifiedFallback();
  await writeFile(
    new URL("../shared/prefetch-fallback.min.ts", import.meta.url),
    "// Generated by build/prefetch-script.ts from client/prefetch-fallback.ts. Do not edit.\n" + "export const FALLBACK = " + JSON.stringify(code) + ";\n",
  );
  console.log(code.length + " chars");
}
